helpers.wgsl:
const MAT_TAU: f32 = 6.283185307179586;
const MAT_PI: f32 = 3.141592653589793;
const MAT_INV_2_24: f32 = 5.960464477539063e-8;

var<private> mat_mesh_uv: vec3f = vec3f(0.0, 0.0, 0.0);
var<private> mat_mesh_color: vec4f = vec4f(1.0, 1.0, 1.0, 1.0);

fn mat_set_mesh_attrs(uv: vec2f, has_uv: bool, color: vec4f) {
  mat_mesh_uv = vec3f(uv, select(0.0, 1.0, has_uv));
  mat_mesh_color = color;
}

fn mat_clamp01(x: f32) -> f32 {
  if (x < 0.0) { return 0.0; }
  if (x > 1.0) { return 1.0; }
  return x;
}

fn mat_smoothstep(e0: f32, e1: f32, x: f32) -> f32 {
  let t = mat_clamp01((x - e0) / (e1 - e0));
  return t * t * (3.0 - 2.0 * t);
}

fn mat_sin01(x: f32) -> f32 {
  return 0.5 + 0.5 * sin(MAT_TAU * x);
}

fn mat_unit(h: u32) -> f32 {
  return f32(h >> 8u) * MAT_INV_2_24;
}

fn mat_finite(x: f32) -> bool {
  return abs(x) <= 3.4028234e38;
}

// fbm3 octave count of the TS fbm3: floor, 0 -> 1, clamped to 1..6.
fn mat_octaves(o: f32) -> u32 {
  return u32(clamp(floor(o), 1.0, 6.0));
}

fn pcg_hash(x: u32) -> u32 {
  let state = x * 747796405u + 2891336453u;
  let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
  return (word >> 22u) ^ word;
}

// f32 -> u32 like the TS 'x >>> 0' for non-negative integral values (wraps at 2^32 instead of saturating).
fn f32_to_u32_wrap(x: f32) -> u32 {
  if (x >= 4294967296.0) { return u32(x - 4294967296.0); }
  if (x <= 0.0) { return 0u; }
  return u32(x);
}

fn noise_lattice(c: vec3i, seed: u32) -> f32 {
  let u = bitcast<vec3u>(c);
  let h = pcg_hash(u.x + pcg_hash(u.y + pcg_hash(u.z + pcg_hash(seed))));
  return f32(h >> 8u) * (1.0 / 16777216.0) * 2.0 - 1.0;
}

fn value_noise3(p: vec3f, seed: u32) -> f32 {
  let fl = floor(p);
  let i = vec3i(fl);
  let f = p - fl;
  let u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  let a = noise_lattice(i, seed);
  let b = noise_lattice(i + vec3i(1, 0, 0), seed);
  let c = noise_lattice(i + vec3i(0, 1, 0), seed);
  let d = noise_lattice(i + vec3i(1, 1, 0), seed);
  let e = noise_lattice(i + vec3i(0, 0, 1), seed);
  let g = noise_lattice(i + vec3i(1, 0, 1), seed);
  let h = noise_lattice(i + vec3i(0, 1, 1), seed);
  let k = noise_lattice(i + vec3i(1, 1, 1), seed);
  let x00 = a + (b - a) * u.x;
  let x10 = c + (d - c) * u.x;
  let x01 = e + (g - e) * u.x;
  let x11 = h + (k - h) * u.x;
  let y0 = x00 + (x10 - x00) * u.y;
  let y1 = x01 + (x11 - x01) * u.y;
  return y0 + (y1 - y0) * u.z;
}

fn fbm3(p: vec3f, octaves: u32, seed: u32) -> f32 {
  let n = clamp(octaves, 1u, 6u);
  var sum = 0.0;
  var norm = 0.0;
  var gain = 1.0;
  var q = p;
  for (var k = 0u; k < n; k = k + 1u) {
    sum = sum + gain * value_noise3(q, seed + k);
    norm = norm + gain;
    gain = gain * 0.5;
    q = q * 2.0;
  }
  return sum / norm;
}

// Blend modes of math.mix_color (order of BLEND_MODES in blend.ts; CPU twin: blendChannel).
fn mat_blend1(m: u32, a: f32, b: f32) -> f32 {
  if (m == 1u) { return a + b; }
  if (m == 2u) { return a - b; }
  if (m == 3u) { return a * b; }
  if (m == 4u) { return 1.0 - (1.0 - a) * (1.0 - b); }
  if (m == 5u) {
    if (a < 0.5) { return 2.0 * a * b; }
    return 1.0 - 2.0 * (1.0 - a) * (1.0 - b);
  }
  if (m == 6u) { return min(a, b); }
  if (m == 7u) { return max(a, b); }
  if (m == 8u) { return abs(a - b); }
  if (m == 9u) {
    if (b != 0.0) { return a / b; }
    return a;
  }
  if (m == 10u) {
    if (a == 0.0) { return 0.0; }
    let d = 1.0 - b;
    if (d <= 0.0) { return 1.0; }
    return min(1.0, a / d);
  }
  if (m == 11u) {
    if (b <= 0.0) { return 0.0; }
    return clamp(1.0 - (1.0 - a) / b, 0.0, 1.0);
  }
  if (m == 12u) { return (1.0 - a) * b * a + a * (1.0 - (1.0 - b) * (1.0 - a)); }
  if (m == 13u) {
    if (b > 0.5) { return a + 2.0 * (b - 0.5); }
    return a + 2.0 * b - 1.0;
  }
  return b;
}

fn mat_blend(m: u32, a: vec3f, b: vec3f) -> vec3f {
  return vec3f(mat_blend1(m, a.x, b.x), mat_blend1(m, a.y, b.y), mat_blend1(m, a.z, b.z));
}

// Triplanar weights |n|^4 / sum (equal thirds when n = 0).
fn mat_tri_weights(n: vec3f) -> vec3f {
  let n2 = n * n;
  let w = n2 * n2;
  let sum = w.x + w.y + w.z;
  if (sum > 1e-12) { return w / sum; }
  return vec3f(1.0 / 3.0);
}

fn mat_pat_noise(q: vec3f, P: array<f32, 6>, ax: u32, seed: u32) -> f32 {
  return 0.5 + 0.5 * P[1] * fbm3(q, mat_octaves(P[0]), seed) + P[2];
}
